// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;

    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        vm.deal(caller, 1 ether);

        vm.prank(caller);
        bool ok;
        try c.assertionDisputedCallback(keccak256(abi.encodePacked("test", caller))) {
            ok = true;
        } catch {
            ok = false;
        }

        vm.prank(caller);
        bool ok2;
        try c.requestPrice(keccak256(abi.encodePacked("id", caller)), block.timestamp, "") {
            ok2 = true;
        } catch {
            ok2 = false;
        }

        assertTrue(!ok2);
    }
}
